window.E14_MOTOR_READY=new Promise(res=>{try{const s=atob('');const u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);new GLTFLoaderX().parse(u.buffer,'',g=>{window.E14_MOTOR=g.scene;res(g.scene)},err=>{console.error('motor glb',err);res(null)})}catch(e){console.error(e);res(null)}});
